/**
 * check-manifest — the record type of schema id `specstride.manifest/1`, annex D, §D.8.
 *
 * Generated by `scripts/types.mjs` from `schemas/check-manifest.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface CheckManifest {
  /**
   * Schema id
   *
   * Type in words: Text.
   */
  schema: string;
  /**
   * Phase number
   *
   * Type in words: Whole number.
   */
  phase: number;
  /**
   * Hash of the manifest, verified before every check
   *
   * Type in words: Text.
   */
  hash: string;
  /**
   * The search path for executables as it was at launch
   *
   * Type in words: Text.
   */
  searchPath: string;
  /**
   * The commands of the phase itself, in the order of the verification plan; the commands of earlier phases are in their own manifests, and the cumulative verification gate takes its commands from the manifests of the phases it covers (F105-FR-020)
   *
   * Type in words: List of records.
   */
  entries: Array<{
    /**
     * Id of the command, stable inside the run
     *
     * Type in words: Text.
     */
    id: string;
    /**
     * Kind of the identity: `command`, or a registered kind
     *
     * Type in words: Member of an open set.
     */
    kind: string;
    /**
     * The fixed argument list
     *
     * Type in words: List of text.
     */
    argv?: unknown[];
    /**
     * The identity record of the check runner: for `command` the absolute path of the executable with size and hash
     *
     * Type in words: Record.
     */
    pin: Record<string, unknown>;
    /**
     * File and line of the declaration
     *
     * Type in words: Record.
     */
    provenance: Record<string, unknown>;
    /**
     * Time limit of the command
     *
     * Type in words: Whole number of seconds.
     */
    timeLimit: number;
    /**
     * Tasks the declaration names
     *
     * Type in words: List of text.
     */
    tasks?: unknown[];
    /**
     * Steps, for the step runner
     *
     * Type in words: List of records.
     */
    steps?: unknown[];
    /**
     * Declared reads and writes, ignored paths included; or `sideEffects: none` together with `reads: tree`
     *
     * Type in words: Lists of path prefixes.
     */
    reads?: unknown[];
    /**
     * Declared reads and writes, ignored paths included; or `sideEffects: none` together with `reads: tree`
     *
     * Type in words: Lists of path prefixes.
     */
    writes?: unknown[];
    /**
     * An exclusive resource the command needs
     *
     * Type in words: Text.
     */
    resource?: string;
    /**
     * Whether the command belongs to the inner check set. The writer sets it true for every entry: the inner check set is the manifest, and only the runtime takes a command out of it during a phase attempt, with a reason (F105-FR-020; F115-FR-013)
     *
     * Type in words: Truth value.
     */
    inner: boolean;
  }>;
}
